"use strict";

const parts = [
  require("./lib/a"),
  require("./lib/b"),
  require("./lib/c"),
  require("./lib/d"),
  require("./lib/e"),
];

module.exports = function cacheGraphProbe() {
  const sum = parts.reduce((acc, part) => acc + part.value, 0);
  return {
    sum,
    summary: `cache-graph/v2/${sum}/${parts.map((part) => part.label).join("")}`,
  };
};
